  width: 40px !important;   
  height: 40px !important;
  background: transparent !important; 
  overflow: visible !important; 

  right: -54px !important;  
  top: 1px !important;      
}

.input-btn-ai::after, .send-btn-custom::after {
  content: "";
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%); 

