/* ==========================================
   8. 顶栏样式设置
   ========================================== */
:root {
  --chat-header-bg: #F1F1F1;
  --chat-header-title-color: #CF9B48;
  --chat-header-title-size: 16px; 

  --info-btn-icon: url('https://img.heliar.top/file/1779095667747_retouch_2026051817092494.png');
  --btn-info-scale: 0.8; 
  --btn-info-translate-x: 0px;  
  --btn-info-translate-y: 1px;  
}

.header-avatar-container {
  display: none !important;
}

.header-btn-phone, 
.header-btn-video {
  opacity: 0 !important;
}

.chat-header-title {
  position: relative !important; 
  overflow: visible !important; 
  transform: translate(0px, -5px) !important;
}

.chat-header-title::before {
  content: "";
  position: absolute;
  background: url('https://img.heliar.top/file/1779095674833_retouch_2026051817121030.png') no-repeat left center/contain;
  pointer-events: none; 
  width: 80px;  
  height: 15px; 
  left: 0px;      
  bottom: -10px;  
}

.chat-header-title::after {
  content: "";
  position: absolute;
  background: url('https://img.heliar.top/file/1779095667209_retouch_2026051817082930.png') no-repeat center/contain;
  pointer-events: none;
  width: 80px; 
  height: 22px; 
  right: -90px;   
  top: -2px;      
}
/* ==========================================
   在 AI/发送 按钮的粉色贴图正中心写上白色“发送”
   ========================================== */
.input-btn-ai::before, .send-btn-custom::before {
  content: "发送" !important;
  position: absolute;
  top: 50%; 
  left: 50%;
  transform: translate(-50%, -50%); 

  color: #FFFFFF !important;      /* 纯白文字 */
  font-size: 12px !important;     /* 字体大小（根据贴图大小调整） */
  font-weight: bold !important;   /* 字体加粗 */
  letter-spacing: 1px !important; /* 微微拉开一点字间距更好看 */
  margin-left: 1px !important;    /* 修正间距带来的轻微偏移，保证绝对居中 */

  z-index: 10 !important;         /* 强制浮在粉色贴图的上方 */
  pointer-events: none !important;/* 保证文字不会阻挡手指的点击 */
  white-space: nowrap !important; /* 防止文字换行 */
}
* =========================================
   1. 微方圆气泡（整体缩小 + 高度压缩，仅上下粉色晕染）
========================================= */
:root {
  /* 我方气泡 */
  --bubble-me-bg: #fffbfb;             /* 极浅粉白底 */
  --bubble-me-color: #5c4b4b;          /* 暖灰文字 */

  /* 👇 【重点缩小】上下边距极限压缩为6px，左右14px，高度大幅变矮 */
  --bubble-me-padding: 6px 14px;       
  /* 👇 【整体缩小】字号等比例缩小 */
  --bubble-me-font-size: 13px;         

  --bubble-me-border: none;            

  /* 配合小气泡，阴影的厚度也稍微减弱了一点点，显得更精致 */
  --bubble-me-shadow: 
    inset 0 3px 5px -2px #fadce3,      /* 顶部粉色内阴影 */
    inset 0 -3px 5px -2px #fadce3;     /* 底部粉色内阴影 */

  /* 👇 【重点修改】圆角改为 10px，介于“大圆润”和“纯直角”之间，完美的微方圆 */
  --bubble-me-radius: 10px;            
  --bubble-me-radius-first: 10px;
  --bubble-me-radius-mid: 10px;
  --bubble-me-radius-last: 10px;

  /* 对方气泡（同步缩小） */
  --bubble-them-bg: #fffbfb;
  --bubble-them-color: #5c4b4b;
  --bubble-them-padding: 6px 14px;
  --bubble-them-font-size: 13px;

  --bubble-them-border: none;
  --bubble-them-shadow: 
    inset 0 3px 5px -2px #fadce3,
    inset 0 -3px 5px -2px #fadce3;

  --bubble-them-radius: 10px;
  --bubble-them-radius-first: 10px;
  --bubble-them-radius-mid: 10px;
  --bubble-them-radius-last: 10px;
}

/* 必须设置相对定位和允许溢出，颜文字才不会被切掉 */
.bubble-me-custom,
.bubble-them-custom {
  position: relative !important;
  overflow: visible !important;
}

/* =========================================
   2. 气泡顶部颜文字装饰
========================================= */

/* 给气泡左上角加上悬浮的颜文字 */
.bubble-me-custom::before,
.bubble-them-custom::before {
  content: ",,0-0,,";           
  position: absolute;
  top: -12px;                   /* 配合变矮的气泡微调了高度 */
  left: 8px;                    /* 配合变方的圆角微调了位置 */
  font-size: 11px;              /* 颜文字也等比例变小一点点 */
  color: #b8acac;               
  font-weight: 500;
  letter-spacing: 1px;          
  pointer-events: none;
}

/* 增加消息顶部间距，给小颜文字留出空间 */
.chat-message-list-custom .msg-bubble-container {
  margin-top: 5px !important;
  margin-bottom: 5px !important;
}


